CREATE TABLE `solution_service_relations` (`solution_id` INT NOT NULL, `service_id` INT NOT NULL, PRIMARY KEY (`solution_id`,`service_id`), CONSTRAINT `solution_service_relations_solution_id_fkey` FOREIGN KEY (`solution_id`) REFERENCES `solutions` (`id`) ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT `solution_service_relations_service_id_fkey` FOREIGN KEY (`service_id`) REFERENCES `services` (`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;